// A grid of coordinates, and a Google URL for each one.
//
// single-item input: Settings emits one row and the grid is built once per run.
const cfg = $('Settings').first().json;

const lat = Number(cfg.centre_lat);
const lng = Number(cfg.centre_lng);
if (!isFinite(lat) || lat < -90 || lat > 90) throw new Error('centre_lat must be a number between -90 and 90. Got: ' + cfg.centre_lat);
if (!isFinite(lng) || lng < -180 || lng > 180) throw new Error('centre_lng must be a number between -180 and 180. Got: ' + cfg.centre_lng);

const keyword = String(cfg.keyword || '').trim();
if (!keyword) throw new Error('Set keyword in Settings to what a customer would type, for example dentist');
if (!String(cfg.business_name || '').trim()) throw new Error('Set business_name in Settings to your name exactly as Google spells it');

// An odd size puts your own address in the middle square, which is the point of
// reference the whole map is read against.
let size = Math.round(Number(cfg.grid_size) || 3);
if (size < 3) size = 3;
if (size % 2 === 0) size += 1;
if (size > 7) size = 7;   // 49 requests a week is already a lot for a map

const spacing = Math.max(0.2, Number(cfg.spacing_km) || 2);
const radius = Math.max(100, Number(cfg.radius_m) || 1000);

// A degree of latitude is the same length everywhere; a degree of longitude
// shrinks towards the poles, so it has to be divided by the cosine or the grid
// comes out as a rectangle that is wrong in one direction.
const dLat = spacing / 110.574;
const dLng = spacing / (111.320 * Math.cos((lat * Math.PI) / 180));

// The Code node sandbox has no `URL`, but it does have `Buffer` - which is the
// only reason this can be assembled here instead of in another service.
function b64(s) {
  try { return Buffer.from(s, 'utf8').toString('base64'); }
  catch (e) { return btoa(unescape(encodeURIComponent(s))); }
}

// The coordinate form of Google's uule. Verified live: sent for 40.7580,
// -73.9855 Google reported its own location as `10036, New York, NY` and
// returned a Manhattan pack; the same request for Brooklyn returned a Brooklyn
// one. Repeating each point gave the same place back both times.
function uule(la, ln) {
  const body = 'role: 1\nproducer: 12\nprovenance: 6\ntimestamp: 0\n'
    + 'latlng {\n  latitude_e7: ' + Math.round(la * 1e7) + '\n  longitude_e7: ' + Math.round(ln * 1e7) + '\n}\n'
    + 'radius: ' + radius + '\n';
  return 'a+' + b64(body);
}

const half = (size - 1) / 2;
const points = [];

// Row 0 is the northern edge, so the map printed later reads the way a map
// should rather than upside down.
for (let row = 0; row < size; row++) {
  for (let col = 0; col < size; col++) {
    const pLat = lat + (half - row) * dLat;
    const pLng = lng + (col - half) * dLng;
    points.push({
      row: row,
      col: col,
      is_centre: row === half && col === half,
      lat: Number(pLat.toFixed(6)),
      lng: Number(pLng.toFixed(6)),
      grid_size: size,
      serp_url: 'https://www.google.com/search?q=' + encodeURIComponent(keyword)
        + '&gl=' + encodeURIComponent(String(cfg.country || 'us').toLowerCase())
        + '&hl=en&brd_json=1&uule=' + encodeURIComponent(uule(pLat, pLng)),
    });
  }
}

return points.map(function (p) { return { json: p }; });

// single-item input: the loop hands over one grid point at a time, so one
// response arrives here per pass and there is nothing else to read.
function unwrapSerp(x) {
  // `format: json` returns the whole HTTP envelope with the parsed SERP nested
  // in `body` as a STRING. Reading `snack_pack` off the top level finds nothing
  // and reports that you rank nowhere, which is the wrong direction to fail in.
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

function key(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

const cfg = $('Settings').first().json;
const mine = key(cfg.business_name);
const point = $('Loop Over The Grid').first().json;
const body = unwrapSerp($input.first().json);

if (body.error) {
  throw new Error('Bright Data SERP returned an error at point ' + point.row + ',' + point.col + ': ' + JSON.stringify(body.error).slice(0, 300));
}

const pack = body.snack_pack || [];

// Every entry carries a base64 JPEG of the storefront. Left in, one grid point
// is hundreds of kilobytes of nothing anybody will look at.
const listed = pack.map(function (e, i) {
  return {
    position: i + 1,
    name: String(e.name || '').trim(),
    rating: e.rating == null ? null : Number(e.rating),
    reviews: e.reviews_cnt == null ? null : Number(e.reviews_cnt),
  };
});

let rank = null;
for (let i = 0; i < listed.length; i++) {
  const there = key(listed[i].name);
  if (!there || !mine) continue;
  if (there === mine || there.indexOf(mine) >= 0 || mine.indexOf(there) >= 0) { rank = i + 1; break; }
}

return [{ json: {
  row: point.row,
  col: point.col,
  is_centre: point.is_centre,
  lat: point.lat,
  lng: point.lng,
  grid_size: point.grid_size,
  // What Google thought the searcher's location was. Worth carrying: it is the
  // one field that proves the coordinate was honoured rather than ignored.
  resolved_location: String((body.general && body.general.location) || ''),
  pack_size: listed.length,
  rank: rank,
  in_pack: rank !== null,
  above_me: listed.filter(function (e) { return rank === null || e.position < rank; }).map(function (e) { return e.name; }),
  pack: listed,
}}];

// The loop's done output carries every point it read.
const cfg = $('Settings').first().json;
const points = $input.all().map(function (i) { return i.json; }).filter(function (p) { return p.grid_size; });

if (!points.length) {
  throw new Error('The grid loop finished without reading a single point. Check the Bright Data credential on Search From That Point.');
}

// If Google ignored the coordinate everywhere, the map is one reading repeated
// N times and every conclusion drawn from it would be wrong. That is worth
// stopping for rather than drawing.
const located = points.filter(function (p) {
  return p.resolved_location && p.resolved_location.toLowerCase() !== 'unknown';
});
if (!located.length) {
  throw new Error('Google reported no location for any of the ' + points.length +
    ' points, so every square is the same search repeated. The uule was not honoured - re-run, and if it persists check the SERP zone.');
}

const found = points.filter(function (p) { return p.in_pack; });
const ranks = found.map(function (p) { return p.rank; });
const avg = ranks.length ? ranks.reduce(function (a, b) { return a + b; }, 0) / ranks.length : null;
const size = points[0].grid_size;

return [{ json: {
  business: String(cfg.business_name || ''),
  keyword: String(cfg.keyword || ''),
  grid_size: size,
  point_count: points.length,
  located_count: located.length,
  in_pack: found.length,
  coverage_pct: Math.round((found.length / points.length) * 1000) / 10,
  avg_rank: avg === null ? null : Math.round(avg * 100) / 100,
  best_rank: ranks.length ? Math.min.apply(null, ranks) : null,
  points: points,
  run_on: new Date().toISOString().slice(0, 10),
  watch_key: String(cfg.business_name || '') + '|' + String(cfg.keyword || ''),
}}];

// single-item input: one map per run.
//
// The score is read by name, not off $input. `Read Last Week` sits directly
// above this node and a Data Table read *replaces* the items with its own rows -
// so $input here is the history, and on a first run it is one empty item. Read
// that way every field below comes out undefined and the report prints
// "undefined of undefined points" on a run where every node is green.
const now = $('Score The Map').first().json;

// The table is read by name because it sits between this node and the score.
const rows = $('Read Last Week').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.watch_key; });
const prior = rows.filter(function (r) { return String(r.watch_key) === now.watch_key; })
  .sort(function (a, b) { return String(b.run_on || '').localeCompare(String(a.run_on || '')); })[0];

const was = prior ? Number(prior.coverage_pct) : null;
const delta = (was === null || isNaN(was)) ? null : Math.round((now.coverage_pct - was) * 10) / 10;

return [{ json: Object.assign({}, now, {
  previous_coverage: was,
  coverage_delta: delta,
  previous_run: prior ? String(prior.run_on || '') : '',
  // A first run has nothing to compare against, and saying "up 62 points" on
  // week one would be a lie made of arithmetic.
  is_first_run: !prior,
}) }];

// single-item input: the comparison folded the whole grid onto one item.
//
// This is the part of a grid that a rank number cannot give you. A competitor
// who beats you at two points on the far edge is not the same problem as one who
// beats you at nine, and the tally says which you have.
const j = $input.first().json;
const mineKey = String(j.business || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const tally = {};
(j.points || []).forEach(function (p) {
  (p.above_me || []).forEach(function (name) {
    const k = String(name).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (!k || k === mineKey) return;
    if (!tally[k]) tally[k] = { name: name, points: 0, best: 99 };
    tally[k].points += 1;
    const pos = (p.pack || []).filter(function (e) { return e.name === name; })[0];
    if (pos && pos.position < tally[k].best) tally[k].best = pos.position;
  });
});

const rivals = Object.keys(tally).map(function (k) { return tally[k]; })
  .sort(function (a, b) { return b.points - a.points; })
  .slice(0, 6)
  .map(function (r) {
    return { name: r.name, points: r.points, share_pct: Math.round((r.points / j.point_count) * 1000) / 10, best_position: r.best };
  });

return [{ json: Object.assign({}, j, { rivals: rivals }) }];

// single-item input: one grid, one picture of it.
//
// The ranks are printed in the shape of the ground they were measured on,
// north at the top. A column of numbers sorted by rank would hold the same
// data and hide the only thing a grid is for - that the weakness has a
// direction.
const j = $input.first().json;
const size = j.grid_size;

const cell = {};
(j.points || []).forEach(function (p) { cell[p.row + ',' + p.col] = p; });

const lines = [];
for (let row = 0; row < size; row++) {
  const parts = [];
  for (let col = 0; col < size; col++) {
    const p = cell[row + ',' + col];
    if (!p) { parts.push(' ? '); continue; }
    const mark = p.in_pack ? String(p.rank) : '-';
    parts.push(p.is_centre ? '[' + mark + ']' : ' ' + mark + ' ');
  }
  lines.push(parts.join(' '));
}

const map = lines.join('\n');
const legend = '1-3 = your position in the pack at that point, - = not in the pack there, [ ] = your centre point.';

return [{ json: Object.assign({}, j, { map: map, legend: legend }) }];

