// single-item input: one map, one report.
const j = $('Draw The Map').first().json;
const raw = $input.first().json;
const summary = String(raw.text || raw.output || raw.response || '').trim();

const cfg = $('Settings').first().json;
const head = j.business + ' - "' + j.keyword + '" - ' + j.run_on;

const trend = j.is_first_run
  ? 'First run, so there is nothing to compare it with yet.'
  : (j.coverage_delta === null
      ? ''
      : (j.coverage_delta === 0
          ? 'Unchanged since ' + j.previous_run + '.'
          : (j.coverage_delta > 0 ? 'Up ' : 'Down ') + Math.abs(j.coverage_delta) +
            ' points since ' + j.previous_run + '.'));

const rivalLines = (j.rivals || []).map(function (r) {
  return '- ' + r.name + ' - above you at ' + r.points + ' of ' + j.point_count + ' points (' + r.share_pct + '%), best position ' + r.best_position;
});

const slack = ['*' + head + '*',
  'In the pack at ' + j.in_pack + ' of ' + j.point_count + ' points (' + j.coverage_pct + '%), average position ' +
    (j.avg_rank === null ? 'n/a' : j.avg_rank) + '. ' + trend,
  '',
  '```',
  j.map,
  '```',
  j.legend];
if (summary) { slack.push(''); slack.push(summary); }
if (rivalLines.length) { slack.push(''); slack.push('*Who is above you*'); rivalLines.forEach(function (l) { slack.push(l); }); }

const html = ['<h2>' + head + '</h2>',
  '<p>In the pack at <b>' + j.in_pack + ' of ' + j.point_count + '</b> points (' + j.coverage_pct +
    '%), average position ' + (j.avg_rank === null ? 'n/a' : j.avg_rank) + '. ' + trend + '</p>',
  summary ? '<p>' + summary + '</p>' : '',
  '<pre style="font-size:16px;line-height:1.6">' + j.map + '</pre>',
  '<p style="color:#666">' + j.legend + '</p>'];
if (rivalLines.length) {
  html.push('<h3>Who is above you</h3><ul>');
  (j.rivals || []).forEach(function (r) {
    html.push('<li>' + r.name + ' - above you at ' + r.points + ' of ' + j.point_count +
      ' points (' + r.share_pct + '%), best position ' + r.best_position + '</li>');
  });
  html.push('</ul>');
}
html.push('<p style="color:#666">The local pack is three results deep. A dash means not in the top three at that point, not a position further down.</p>');

return [{ json: Object.assign({}, j, {
  summary: summary,
  message: slack.join('\n'),
  html: html.join(''),
  subject: 'Local pack map: ' + j.business + ' - ' + j.keyword + ' - ' + j.coverage_pct + '% coverage',
  report_to: String(cfg.report_to || ''),
}) }];
